python3 - <<'EOF'
import json

with open('batches/batch_0010.json', encoding='utf-8') as f:
    data = json.load(f)

def fix(s):
    if not s:
        return s
    out = []
    buf = bytearray()
    for ch in s:
        if ord(ch) <= 255:
            buf.append(ord(ch))
        else:
            if buf:
                try:
                    out.append(buf.decode('utf-8'))
                except Exception:
                    out.append(buf.decode('utf-8', errors='replace'))
                buf = bytearray()
            out.append(ch)
    if buf:
        try:
            out.append(buf.decode('utf-8'))
        except Exception:
            out.append(buf.decode('utf-8', errors='replace'))
    return ''.join(out)

out = []
for item in data:
    new = dict(item)
    for k in ('title','desc','body'):
        if k in new and new[k]:
            new[k] = fix(new[k])
    out.append(new)

with open('batches_out/batch_0010_fixed_preview.json', 'w', encoding='utf-8') as f:
    json.dump(out, f, ensure_ascii=False, indent=1)

print("done", len(out))
EOF
